function compute(arr){ return arr.map(p=>{ const c=p.shares*p.avgCost, m=p.shares*p.currentPrice, pnl=m-c; return {...p,cost:c,market:m,pnl,pnlPct:(pnl/c)*100}; }); }

const twData = compute(twPortfolio), usData = compute(usPortfolio);
const twStockMarket = twData.reduce((s,p)=>s+p.market,0);
const twTotal = twStockMarket + twCash;
const twTotalCost = twData.reduce((s,p)=>s+p.cost,0);
const twPnl = twStockMarket - twTotalCost;
