function defPos(sym, mkt) { return (mkt === 'TW' ? twPortfolio : usPortfolio).find(x => x.symbol === sym); }
function defCcy(mkt) { return mkt === 'TW' ? 'NT$' : '$'; }
function defFlag(mkt) { return mkt === 'TW' ? '🇹🇼' : '🇺🇸'; }
function defUnit(p, mkt) {
  if (mkt === 'TW' && p.shares >= 1000 && p.shares % 1000 === 0) return (p.shares/1000) + ' 張(全)';
  return p.shares + ' 股(全)';
}

